// An ImageProvider is a cache key plus a loader. Nothing more.
class BlobImage extends ImageProvider<BlobImage> {
  const BlobImage(this.id, this.store);

  final String id;
  final BlobStore store;

  // The key decides cache identity: two BlobImage('avatar-7') are one entry.
  @override
  Future<BlobImage> obtainKey(ImageConfiguration configuration) =>
      SynchronousFuture<BlobImage>(this);

  // Called only on a cache miss. loadBuffer is deprecated; loadImage is current.
  @override
  ImageStreamCompleter loadImage(BlobImage key, ImageDecoderCallback decode) {
    return MultiFrameImageStreamCompleter(
      codec: _load(key, decode),
      scale: 1.0,
      debugLabel: 'blob:${key.id}',
    );
  }

  Future<ui.Codec> _load(BlobImage key, ImageDecoderCallback decode) async {
    final Uint8List bytes = await store.read(key.id);
    return decode(await ui.ImmutableBuffer.fromUint8List(bytes));
  }

  @override
  bool operator ==(Object other) => other is BlobImage && other.id == id;

  @override
  int get hashCode => id.hashCode;
}

