// Snap to a ladder so one photo does not occupy five cache entries.
int decodeWidth(double slotDp, double dpr) {
  const ladder = [128, 256, 512, 1024];
  final want = (slotDp * dpr).round();
  return ladder.firstWhere((w) => w >= want, orElse: () => ladder.last);
}

