class PhotoTile extends StatelessWidget {
  const PhotoTile({super.key, required this.photo, required this.slotDp});

  final Photo photo;      // id, path, width, height, blurHash
  final double slotDp;

  @override
  Widget build(BuildContext context) {
    final dpr = MediaQuery.devicePixelRatioOf(context);
    final w = ladderWidth(slotDp, dpr);
    return AspectRatio(
      // From the payload: the tile reserves its box before any byte arrives.
      aspectRatio: photo.width / photo.height,
      child: Stack(
        fit: StackFit.expand,
        children: [
          BlurHash(hash: photo.blurHash, decodingWidth: 32, decodingHeight: 32),
          CachedNetworkImage(
            imageUrl: variantUrl(photo.path, w),
            cacheKey: 'photo:${photo.id}:$w',   // stable across URL signing
            memCacheWidth: w,                   // decode == what we downloaded
            fadeInDuration: const Duration(milliseconds: 120),
            fit: BoxFit.cover,
          ),
        ],
      ),
    );
  }
}

