Future<List<File>> pickAttachments() async {
  // No permission request here: the OS picker runs out of process.
  final List<XFile> picked = await _picker.pickMultiImage(
    limit: 10,
    maxWidth: 2048,          // platform-side resize, off the Dart isolate
    imageQuality: 85,        // re-encodes to JPEG
    requestFullMetadata: false, // iOS: skips the Photos permission entirely
  );
  return Future.wait(picked.map(_persist));
