// ❌ Uploading straight from XFile.path: the temp copy can be gone by retry time.
// ✅ Move it somewhere you control first.
Future<File> _persist(XFile x) async {
  final dir = await getApplicationSupportDirectory();
  final target = File('${dir.path}/outbox/${DateTime.now().microsecondsSinceEpoch}_${x.name}');
  await target.parent.create(recursive: true);
  return File(x.path).copy(target.path);
}

// Android only: the activity can be killed while the camera is in front.
// Without this the captured photo is lost with no error at all.
Future<void> recoverLostPicks() async {
  if (!Platform.isAndroid) return;
  final LostDataResponse lost = await _picker.retrieveLostData();
  if (lost.isEmpty) return;
  if (lost.exception != null) {
    reportError(lost.exception!);
    return;
  }
  for (final x in lost.files ?? <XFile>[]) {
    await _persist(x);
  }
}

