// ❌ Uploads the file exactly as the phone wrote it: the orientation tag is
//    never applied, and on iOS the container may be HEIC.
Future<void> uploadRaw(XFile picked) async {
  await api.upload(await picked.readAsBytes()); // sideways once it leaves you
}

// ✅ Bake the rotation into the pixels and normalise the container.
Future<Uint8List> normalise(XFile picked) async {
  final out = await FlutterImageCompress.compressWithFile(
    picked.path,
    minWidth: 2048, // an upper bound, not a target — it never upscales
    minHeight: 2048,
    quality: 82,
    format: CompressFormat.jpeg, // HEIC in, JPEG out
    autoCorrectionAngle: true,   // applies the EXIF orientation tag
    keepExif: false,             // drops GPS along with it, usually what you want
  );
  return out!;
}

// The pure-Dart equivalent, for when you already hold the bytes.
Uint8List bakeUpright(Uint8List bytes) {
  final decoded = img.decodeImage(bytes)!;      // pixels, still unrotated
  final upright = img.bakeOrientation(decoded); // applies and clears the tag
  return img.encodeJpg(upright, quality: 82);
}

