// ❌ Runs on the UI isolate: over a second of frozen frames on a mid-range phone.
Future<Uint8List> shrinkBad(File file) async {
  final bytes = await file.readAsBytes();
  final decoded = img.decodeImage(bytes)!;           // ~48 MB, on the UI isolate
  final small = img.copyResize(decoded, width: 2048);
  return img.encodeJpg(small, quality: 82);          // await changes nothing here
}

// ✅ Preferred: the platform encoder, on a native background thread.
Future<Uint8List> shrink(File file) async {
  final out = await FlutterImageCompress.compressWithFile(
    file.path,
    minWidth: 2048,
    minHeight: 2048,
    quality: 82,
  );
  return out!;
}

// ✅ Fallback when you need the Dart pipeline (custom crop, watermark, filters).
Future<Uint8List> shrinkInIsolate(File file) async {
  final bytes = await file.readAsBytes();   // I/O is already off the UI thread
  return Isolate.run(() {                   // bytes are copied in and back out
    final decoded = img.decodeImage(bytes)!;
    return img.encodeJpg(img.copyResize(decoded, width: 2048), quality: 82);
  });
}

// A spawned isolate has no plugin messenger until you hand it the token.
Future<String> writeInIsolate(Uint8List jpeg) {
  final token = RootIsolateToken.instance!;
  return Isolate.run(() async {
    BackgroundIsolateBinaryMessenger.ensureInitialized(token);
    final dir = await getTemporaryDirectory();       // plugin call now works
    final out = File('${dir.path}/upload.jpg');
    await out.writeAsBytes(jpeg);
    return out.path;
  });
}

