class _ScannerState extends State<Scanner> with WidgetsBindingObserver {
  CameraController? _c;
  bool _busy = false; // the back-pressure the plugin does not give you

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _start();
  }

  Future<void> _start() async {
    final cam = (await availableCameras()).first;
    final c = CameraController(cam, ResolutionPreset.high,
        enableAudio: false, imageFormatGroup: ImageFormatGroup.yuv420);
    await c.initialize();
    await c.lockCaptureOrientation(DeviceOrientation.portraitUp);
    await c.startImageStream(_onFrame);
    if (mounted) setState(() => _c = c);
  }

  void _onFrame(CameraImage image) {
    if (_busy) return; // ✅ drop, do not queue: frames arrive at 30 fps
    _busy = true;
    detect(image.planes.map((p) => p.bytes).toList(), image.width, image.height)
        .whenComplete(() => _busy = false); // runs off the UI isolate
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.inactive) {
      _c?.dispose(); // Android takes the camera away anyway
      _c = null;
    } else if (state == AppLifecycleState.resumed && _c == null) {
      _start();
    }
  }

  @override
  Widget build(BuildContext context) {
    final c = _c;
    if (c == null || !c.value.isInitialized) return const ColoredBox(color: Colors.black);
    // ❌ AspectRatio(aspectRatio: c.value.aspectRatio, child: CameraPreview(c))
    // ✅ CameraPreview already handles the portrait inversion
    return ClipRect(
      child: FittedBox(fit: BoxFit.cover, child: SizedBox(
        width: c.value.previewSize!.height, // landscape frame, swapped for portrait
        height: c.value.previewSize!.width,
        child: CameraPreview(c),
      )),
    );
  }
}

