class MediaStore {
  MediaStore(this._db, {this.budgetBytes = 2 << 30}); // 2 GB
  final Database _db;
  final int budgetBytes;

  Future<Directory> _root() async {
    final dir = Directory('${(await getApplicationSupportDirectory()).path}/media');
    // ❌ getTemporaryDirectory(): iOS purges it under storage pressure
    // ❌ getApplicationDocumentsDirectory(): backed up to iCloud on iOS
    return dir.create(recursive: true);
  }

  Future<File> download(Episode e, {required bool onWifi}) async {
    final rendition = onWifi ? e.high : e.low;
    final file = File('${(await _root()).path}/${e.id}.mp4');
    final part = File('${file.path}.part');

    final res = await dio.download(rendition.url, part.path);
    final expected = int.parse(res.headers.value('content-length')!);
    if (await part.length() != expected) {
      await part.delete();
      throw const MediaException('truncated download');
    }
    await part.rename(file.path); // ✅ atomic: a half file is never playable
    await _db.insert('downloads', {
      'id': e.id, 'path': file.path, 'bytes': expected,
      'rendition': rendition.name, 'last_played': 0, 'pinned': 0,
    }, conflictAlgorithm: ConflictAlgorithm.replace);
    await _evict();
    return file;
  }

  Future<void> _evict() async {
    var total = Sqflite.firstIntValue(
        await _db.rawQuery('SELECT SUM(bytes) FROM downloads'))!;
    if (total <= budgetBytes) return;
    final rows = await _db.query('downloads',
        where: 'pinned = 0', orderBy: 'last_played ASC'); // never evict a pin
    for (final r in rows) {
      if (total <= budgetBytes) break;
      await File(r['path'] as String).delete();
      await _db.delete('downloads', where: 'id = ?', whereArgs: [r['id']]);
      total -= r['bytes'] as int;
    }
  }

  // A crash between the rename and the insert leaves a file no row knows about.
  Future<void> reconcile() async {
    final known = {for (final r in await _db.query('downloads')) r['path']};
    await for (final f in (await _root()).list()) {
      if (!known.contains(f.path)) await f.delete();
    }
  }
}
